import java.io.*; import javax.servlet.http.*; public class HelloServlet extends HttpServlet { @Override protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException { String username = request.getParameter("username"); if (username == null || "".equals(username)) { username = "World"; } String outputbuf = "<html><body>Hello, "+username+"!</body></html>"; response.setContentType("text/html"); Writer writer = response.getWriter(); try { writer.write(outputbuf); } finally { writer.close(); } } }